def one_pass(a, operation):
    # Square 3x3, centred; neutral outside: 1 for erosion, 0 for dilation.
    h,w=len(a),len(a[0])
    out=[]
    for y in range(h):
        row=[]
        for x in range(w):
            values=[a[yy][xx] if 0<=yy<h and 0<=xx<w else int(operation=='erosion')
                    for yy in range(y-1,y+2) for xx in range(x-1,x+2)]
            row.append(min(values) if operation=='erosion' else max(values))
        out.append(row)
    return out

def opening_mask(a):
    return one_pass(one_pass(a,"erosion"),"dilation")

